import { HttpError } from "./errors.ts";
import { one } from "./rest.ts";

export async function requireCmsRequest(request: Request): Promise<void> {
    const authorization = request.headers.get("authorization") ?? "";
    const token = authorization.startsWith("Bearer ") ? authorization.slice(7).trim() : "";
    if (!token) {
        throw new HttpError(401, "invalid CMS API key");
    }
    const configured = Deno.env.get("CMS_PHOTO_ALBUMS_API_KEY")?.trim();
    if (configured) {
        if (!safeEqual(token, configured)) {
            throw new HttpError(401, "invalid CMS API key");
        }
        return;
    }
    const credential = await one("connector_credentials", { credential_key: "cms_api_key" }, "secret_hash");
    const expected = typeof credential?.secret_hash === "string" ? credential.secret_hash : "";
    const actual = await sha256(token);
    if (!expected || !safeEqual(actual, expected)) {
        throw new HttpError(401, "invalid CMS API key");
    }
}

async function sha256(value: string): Promise<string> {
    const bytes = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
    return [...new Uint8Array(bytes)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

function safeEqual(left: string, right: string): boolean {
    if (left.length !== right.length) {
        return false;
    }
    let result = 0;
    for (let index = 0; index < left.length; index++) {
        result |= left.charCodeAt(index) ^ right.charCodeAt(index);
    }
    return result === 0;
}

import { HttpError } from "./errors.ts";

export function requiredEnv(name: string): string {
    const value = Deno.env.get(name)?.trim();
    if (!value) {
        throw new HttpError(500, `${name} is not configured`);
    }
    return value;
}

export function serviceRoleKey(): string {
    return requiredEnv("SUPABASE_SERVICE_ROLE_KEY");
}

export class HttpError extends Error {
    constructor(
        readonly status: number,
        message: string,
    ) {
        super(message);
    }
}

import { HttpError } from "./errors.ts";

export const corsHeaders = {
    "access-control-allow-origin": "*",
    "access-control-allow-headers": "authorization, content-type, x-cms-user-id",
    "access-control-allow-methods": "GET, POST, DELETE, OPTIONS",
};

export function json(value: unknown, status = 200): Response {
    return new Response(JSON.stringify(value), {
        status,
        headers: { ...corsHeaders, "content-type": "application/json; charset=utf-8" },
    });
}

export function optionsResponse(): Response {
    return new Response("ok", { headers: corsHeaders });
}

export function methodNotAllowed(...methods: string[]): Response {
    return new Response("Method Not Allowed", {
        status: 405,
        headers: { ...corsHeaders, allow: [...methods, "OPTIONS"].join(", ") },
    });
}

export function handleError(error: unknown): Response {
    if (error instanceof HttpError) {
        return json({ error: error.message }, error.status);
    }
    console.error(error);
    return json({ error: "internal error" }, 500);
}

import { HttpError } from "./errors.ts";

export type JsonRecord = Record<string, unknown>;

export function isRecord(value: unknown): value is JsonRecord {
    return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

export async function readJsonObject(request: Request): Promise<JsonRecord> {
    const value = await request.json().catch(() => null);
    if (!isRecord(value)) {
        throw new HttpError(400, "request body must be a JSON object");
    }
    return value;
}

export function requiredId(request: Request, name: string, fallback?: string): number {
    const params = new URL(request.url).searchParams;
    const raw = params.get(name) ?? (fallback ? params.get(fallback) : null);
    const value = typeof raw === "string" && /^[1-9][0-9]*$/.test(raw) ? Number(raw) : Number.NaN;
    if (!Number.isSafeInteger(value) || value <= 0) {
        throw new HttpError(400, `${name} must be a positive integer`);
    }
    return value;
}

export function optionalInteger(value: unknown, name: string, fallback: number): number {
    const number = value === undefined || value === null || value === "" ? fallback : Number(value);
    if (!Number.isSafeInteger(number)) {
        throw new HttpError(400, `${name} must be an integer`);
    }
    return number;
}

export function optionalText(value: unknown, name: string): string | null {
    if (value === undefined || value === null || value === "") {
        return null;
    }
    if (typeof value !== "string") {
        throw new HttpError(400, `${name} must be a string`);
    }
    return value.trim() || null;
}

export function requiredText(value: unknown, name: string): string {
    const text = optionalText(value, name);
    if (!text) {
        throw new HttpError(400, `${name} is required`);
    }
    return text;
}

export function requiredBoolean(value: unknown, name: string): boolean {
    if (typeof value !== "boolean") {
        throw new HttpError(400, `${name} must be a boolean`);
    }
    return value;
}

export function requiredInteger(value: unknown, name: string): number {
    if (value === undefined || value === null || value === "") {
        throw new HttpError(400, `${name} is required`);
    }
    return optionalInteger(value, name, 0);
}

export function camelize(value: unknown): unknown {
    if (Array.isArray(value)) {
        return value.map(camelize);
    }
    if (!isRecord(value)) {
        return value;
    }
    return Object.fromEntries(
        Object.entries(value).map(([key, entry]) => [
            key.replace(/_([a-z])/g, (_match, letter: string) => letter.toUpperCase()),
            camelize(entry),
        ]),
    );
}

import { requiredEnv, serviceRoleKey } from "./env.ts";
import { HttpError } from "./errors.ts";
import { isRecord, type JsonRecord } from "./records.ts";

const schema = "photo_albums";

export async function rpc(name: string, body: JsonRecord = {}): Promise<unknown> {
    const response = await rest(`rpc/${name}`, {
        method: "POST",
        body: JSON.stringify(body),
    });
    return await response.json();
}

export async function rpcRecord(name: string, body: JsonRecord = {}): Promise<JsonRecord> {
    const value = await rpc(name, body);
    if (!isRecord(value)) {
        throw new HttpError(502, `${name} returned an invalid response`);
    }
    return value;
}

export async function one(
    table: string,
    filters: Record<string, string | number>,
    select = "*",
): Promise<JsonRecord | null> {
    const params = new URLSearchParams({ select, limit: "1" });
    for (const [key, value] of Object.entries(filters)) {
        params.set(key, `eq.${String(value)}`);
    }
    const response = await rest(`${table}?${params}`);
    const rows = (await response.json()) as unknown;
    return Array.isArray(rows) && isRecord(rows[0]) ? rows[0] : null;
}

async function rest(path: string, init: RequestInit = {}): Promise<Response> {
    const key = serviceRoleKey();
    const headers = new Headers(init.headers);
    headers.set("apikey", key);
    if (!key.startsWith("sb_")) {
        headers.set("authorization", `Bearer ${key}`);
    }
    headers.set("accept-profile", schema);
    if (init.method && init.method !== "GET" && init.method !== "HEAD") {
        headers.set("content-profile", schema);
        headers.set("content-type", "application/json");
    }
    const base = requiredEnv("SUPABASE_URL").replace(/\/$/, "");
    const response = await fetch(`${base}/rest/v1/${path}`, { ...init, headers });
    if (!response.ok) {
        throw await restError(response);
    }
    return response;
}

async function restError(response: Response): Promise<HttpError> {
    const body = await response.json().catch(() => null);
    const message =
        isRecord(body) && typeof body.message === "string"
            ? body.message
            : `Supabase request failed (${response.status})`;
    const prefix = /^(validation|conflict|forbidden|not_found):\s*/.exec(message)?.[1];
    if (prefix === "validation") {
        return new HttpError(422, message.replace(/^[^:]+:\s*/, ""));
    }
    if (prefix === "conflict") {
        return new HttpError(409, message.replace(/^[^:]+:\s*/, ""));
    }
    if (prefix === "forbidden") {
        return new HttpError(403, message.replace(/^[^:]+:\s*/, ""));
    }
    if (prefix === "not_found") {
        return new HttpError(404, message.replace(/^[^:]+:\s*/, ""));
    }
    return new HttpError(response.status < 500 ? 422 : 502, message);
}

import { requireCmsRequest } from "./core/auth.ts";
import { handleError, json, optionsResponse } from "./core/http.ts";
import { handleAlbumRoute } from "./routes/albums.ts";
import { handleCategoryRoute } from "./routes/categories.ts";
import { handlePhotoRoute } from "./routes/photos.ts";
import { handleSettingsRoute } from "./routes/settings.ts";
import { handleSetupRoute } from "./routes/setup.ts";

const routeHandlers = [handleSetupRoute, handleCategoryRoute, handleAlbumRoute, handlePhotoRoute, handleSettingsRoute];

export async function handlePhotoAlbumsRequest(request: Request): Promise<Response> {
    try {
        if (request.method === "OPTIONS") {
            return optionsResponse();
        }
        await requireCmsRequest(request);
        const route = routePath(request);
        for (const handler of routeHandlers) {
            const response = await handler(route, request);
            if (response) {
                return response;
            }
        }
        return json({ error: "not found" }, 404);
    } catch (error) {
        return handleError(error);
    }
}

function routePath(request: Request): string {
    const pathname = new URL(request.url).pathname.replace(/\/+$/, "");
    const marker = "/cms-photo-albums";
    const index = pathname.indexOf(marker);
    if (index === -1) {
        return pathname || "/";
    }
    return pathname.slice(index + marker.length) || "/";
}

export const photoBucket = "photo-albums-originals";
export const maxPhotoBytes = 10 * 1024 * 1024;
export const maxPhotoPixels = 40_000_000;
export const maxMultipartOverheadBytes = 256 * 1024;

import { HttpError } from "../core/errors.ts";
import { maxMultipartOverheadBytes } from "./constants.ts";
import { parseSingleMultipartFile } from "./multipartParser.ts";
import type { MultipartFile } from "./multipartParser.ts";

export type { MultipartFile } from "./multipartParser.ts";

export async function readSingleMultipartFile(request: Request, maxFileBytes: number): Promise<MultipartFile> {
    const boundary = multipartBoundary(request.headers.get("content-type"));
    const maxBodyBytes = maxFileBytes + maxMultipartOverheadBytes;
    rejectKnownOversize(request, maxBodyBytes);
    const bytes = await readBoundedBody(request, maxBodyBytes);
    return parseSingleMultipartFile(bytes, boundary, maxFileBytes);
}

function multipartBoundary(contentType: string | null): string {
    if (!contentType || !/^multipart\/form-data(?:;|$)/i.test(contentType.trim())) {
        throw new HttpError(400, "image upload must use multipart/form-data");
    }
    const match = /;\s*boundary=(?:"([^"]+)"|([^;]+))/i.exec(contentType);
    const boundary = (match?.[1] ?? match?.[2] ?? "").trim();
    if (!boundary || boundary.length > 70 || /[\r\n\x00-\x1f\x7f]/.test(boundary)) {
        throw new HttpError(400, "invalid multipart boundary");
    }
    return boundary;
}

function rejectKnownOversize(request: Request, maxBodyBytes: number): void {
    const raw = request.headers.get("content-length")?.trim();
    if (!raw || !/^[0-9]+$/.test(raw)) {
        return;
    }
    const length = Number(raw);
    if (Number.isSafeInteger(length) && length > maxBodyBytes) {
        void request.body?.cancel("multipart body exceeds the configured limit").catch(() => undefined);
        throw new HttpError(413, "file is too large");
    }
}

async function readBoundedBody(request: Request, maxBodyBytes: number): Promise<Uint8Array> {
    if (!request.body) {
        throw new HttpError(400, "invalid multipart body");
    }
    const reader = request.body.getReader();
    const chunks: Uint8Array[] = [];
    let total = 0;
    try {
        for (;;) {
            const result = await reader.read();
            if (result.done) {
                break;
            }
            total += result.value.byteLength;
            if (total > maxBodyBytes) {
                await reader.cancel("multipart body exceeds the configured limit").catch(() => undefined);
                throw new HttpError(413, "file is too large");
            }
            chunks.push(result.value);
        }
    } catch (error) {
        if (error instanceof HttpError) {
            throw error;
        }
        await reader.cancel("invalid multipart body").catch(() => undefined);
        throw new HttpError(400, "invalid multipart body");
    } finally {
        reader.releaseLock();
    }
    return concatenate(chunks, total);
}

function concatenate(chunks: Uint8Array[], total: number): Uint8Array {
    const result = new Uint8Array(total);
    let offset = 0;
    for (const chunk of chunks) {
        result.set(chunk, offset);
        offset += chunk.byteLength;
    }
    return result;
}

import { HttpError } from "../core/errors.ts";

export type MultipartFile = {
    bytes: Uint8Array;
    filename: string;
};

const decoder = new TextDecoder();
const encoder = new TextEncoder();
const maxHeaderBytes = 16 * 1024;

export function parseSingleMultipartFile(bytes: Uint8Array, boundary: string, maxFileBytes: number): MultipartFile {
    const marker = encoder.encode(`--${boundary}`);
    const delimiter = encoder.encode(`\r\n--${boundary}`);
    if (!matchesAt(bytes, marker, 0)) {
        throw new HttpError(400, "invalid multipart body");
    }
    let cursor = marker.length;
    let file: MultipartFile | null = null;
    for (;;) {
        if (matchesAscii(bytes, "--", cursor)) {
            cursor += 2;
            if (cursor === bytes.length) {
                break;
            }
            if (!matchesAscii(bytes, "\r\n", cursor) || cursor + 2 !== bytes.length) {
                throw new HttpError(400, "invalid multipart body");
            }
            break;
        }
        if (!matchesAscii(bytes, "\r\n", cursor)) {
            throw new HttpError(400, "invalid multipart body");
        }
        cursor += 2;
        const headerEnd = indexOf(bytes, encoder.encode("\r\n\r\n"), cursor);
        if (headerEnd < 0 || headerEnd - cursor > maxHeaderBytes) {
            throw new HttpError(400, "invalid multipart headers");
        }
        const headers = parseHeaders(bytes.subarray(cursor, headerEnd));
        const contentStart = headerEnd + 4;
        const nextBoundary = indexOf(bytes, delimiter, contentStart);
        if (nextBoundary < 0) {
            throw new HttpError(400, "invalid multipart body");
        }
        const disposition = contentDisposition(headers.get("content-disposition"));
        if (disposition.filename !== null) {
            if (disposition.name !== "file" || file) {
                throw new HttpError(400, "exactly one file is required");
            }
            const contents = bytes.slice(contentStart, nextBoundary);
            if (contents.byteLength === 0) {
                throw new HttpError(400, "file is empty");
            }
            if (contents.byteLength > maxFileBytes) {
                throw new HttpError(413, "file is too large");
            }
            file = {
                bytes: contents,
                filename: safeFilename(disposition.filename),
            };
        }
        cursor = nextBoundary + 2 + marker.length;
    }
    if (!file) {
        throw new HttpError(400, "file is required");
    }
    return file;
}

function parseHeaders(bytes: Uint8Array): Map<string, string> {
    const value = decoder.decode(bytes);
    const headers = new Map<string, string>();
    for (const line of value.split("\r\n")) {
        const separator = line.indexOf(":");
        if (separator <= 0 || /^[ \t]/.test(line)) {
            throw new HttpError(400, "invalid multipart headers");
        }
        const name = line.slice(0, separator).trim().toLowerCase();
        const content = line.slice(separator + 1).trim();
        if (!/^[a-z0-9!#$%&'*+.^_`|~-]+$/.test(name) || headers.has(name)) {
            throw new HttpError(400, "invalid multipart headers");
        }
        headers.set(name, content);
    }
    return headers;
}

function contentDisposition(value: string | undefined): { filename: string | null; name: string | null } {
    if (!value || !/^form-data(?:;|$)/i.test(value.trim())) {
        throw new HttpError(400, "invalid multipart disposition");
    }
    return {
        filename: dispositionParameter(value, "filename"),
        name: dispositionParameter(value, "name"),
    };
}

function dispositionParameter(value: string, name: string): string | null {
    const expression = new RegExp(`(?:^|;)\\s*${name}=(?:"((?:[^"\\\\]|\\\\.)*)"|([^;]*))`, "i");
    const match = expression.exec(value);
    if (!match) {
        return null;
    }
    const raw = match[1] === undefined ? (match[2] ?? "").trim() : match[1].replace(/\\(.)/g, "$1");
    if (/[\r\n\x00]/.test(raw)) {
        throw new HttpError(400, "invalid multipart disposition");
    }
    return raw;
}

function safeFilename(value: string): string {
    const filename = value.split(/[\\/]/).at(-1)?.trim() ?? "";
    return filename || "image";
}

function indexOf(haystack: Uint8Array, needle: Uint8Array, start: number): number {
    outer: for (let index = start; index <= haystack.length - needle.length; index++) {
        for (let offset = 0; offset < needle.length; offset++) {
            if (haystack[index + offset] !== needle[offset]) {
                continue outer;
            }
        }
        return index;
    }
    return -1;
}

function matchesAt(bytes: Uint8Array, value: Uint8Array, offset: number): boolean {
    return value.every((byte, index) => bytes[offset + index] === byte);
}

function matchesAscii(bytes: Uint8Array, value: string, offset: number): boolean {
    return matchesAt(bytes, encoder.encode(value), offset);
}

import { ascii, malformed, readU16BE, readU32BE, readU64BE, requireBytes, unsupportedAnimation } from "./bytes.ts";
import type { ImageDimensions } from "./types.ts";

type Box = { end: number; payload: number; type: string };
type ParseState = { boxes: number };

const maxBoxes = 4096;

export function isAvif(bytes: Uint8Array): boolean {
    return bytes.length >= 16 && ascii(bytes, 4, 4) === "ftyp" && avifBrand(bytes);
}

export function avifDimensions(bytes: Uint8Array): ImageDimensions {
    const state = { boxes: 0 };
    const top = boxes(bytes, 0, bytes.length, state);
    const ftyp = top.find((box) => box.type === "ftyp");
    const meta = top.find((box) => box.type === "meta");
    const mediaData = top.find((box) => box.type === "mdat");
    if (!ftyp || !meta || !mediaData || mediaData.end === mediaData.payload || !avifBrand(bytes, ftyp)) {
        malformed();
    }
    if (hasBrand(bytes, ftyp, "avis")) {
        unsupportedAnimation();
    }
    requireBytes(bytes, meta.payload, 4);
    const children = boxes(bytes, meta.payload + 4, meta.end, state);
    if (!children.some((box) => box.type === "iloc") || !children.some((box) => box.type === "iinf")) {
        malformed();
    }
    const primaryId = primaryItemId(
        bytes,
        children.find((box) => box.type === "pitm"),
    );
    const iprp = children.find((box) => box.type === "iprp");
    if (!iprp) {
        malformed();
    }
    const propertyBoxes = boxes(bytes, iprp.payload, iprp.end, state);
    const ipco = propertyBoxes.find((box) => box.type === "ipco");
    if (!ipco) {
        malformed();
    }
    const properties = boxes(bytes, ipco.payload, ipco.end, state);
    const dimensionsByProperty = new Map<number, ImageDimensions>();
    const rotationsByProperty = new Map<number, number>();
    properties.forEach((property, index) => {
        if (property.type === "ispe") {
            dimensionsByProperty.set(index + 1, ispeDimensions(bytes, property));
        }
        if (property.type === "irot") {
            requireBytes(bytes, property.payload, 1);
            rotationsByProperty.set(index + 1, bytes[property.payload]! & 0x03);
        }
    });
    if (!dimensionsByProperty.size) {
        malformed();
    }
    if (primaryId !== null) {
        for (const ipma of propertyBoxes.filter((box) => box.type === "ipma")) {
            const propertyIds = associatedPropertyIds(bytes, ipma, primaryId);
            for (const propertyId of propertyIds) {
                const dimensions = dimensionsByProperty.get(propertyId);
                if (dimensions) {
                    const swapsAxes = propertyIds.some((id) => (rotationsByProperty.get(id) ?? 0) % 2 === 1);
                    return swapsAxes ? { width: dimensions.height, height: dimensions.width } : dimensions;
                }
            }
        }
    }
    return [...dimensionsByProperty.values()].sort(
        (left, right) => right.width * right.height - left.width * left.height,
    )[0]!;
}

function avifBrand(bytes: Uint8Array, knownBox?: Box): boolean {
    const box = knownBox ?? boxes(bytes, 0, bytes.length, { boxes: 0 })[0];
    if (!box || box.type !== "ftyp" || box.end - box.payload < 8) {
        return false;
    }
    return hasBrand(bytes, box, "avif") || hasBrand(bytes, box, "avis");
}

function hasBrand(bytes: Uint8Array, box: Box, expected: string): boolean {
    for (let offset = box.payload; offset + 4 <= box.end; offset += 4) {
        if (ascii(bytes, offset, 4) === expected) {
            return true;
        }
    }
    return false;
}

function boxes(bytes: Uint8Array, start: number, end: number, state: ParseState): Box[] {
    const result: Box[] = [];
    let offset = start;
    while (offset < end) {
        requireBytes(bytes, offset, 8);
        if (++state.boxes > maxBoxes) {
            malformed();
        }
        const size32 = readU32BE(bytes, offset);
        const type = ascii(bytes, offset + 4, 4);
        const header = size32 === 1 ? 16 : 8;
        const size = size32 === 0 ? end - offset : size32 === 1 ? readU64BE(bytes, offset + 8) : size32;
        if (size < header || offset + size > end) {
            malformed();
        }
        result.push({ type, payload: offset + header, end: offset + size });
        offset += size;
        if (size32 === 0) {
            break;
        }
    }
    if (offset !== end) {
        malformed();
    }
    return result;
}

function primaryItemId(bytes: Uint8Array, box: Box | undefined): number | null {
    if (!box) {
        return null;
    }
    requireBytes(bytes, box.payload, 6);
    const version = bytes[box.payload]!;
    return version === 0 ? readU16BE(bytes, box.payload + 4) : readU32BE(bytes, box.payload + 4);
}

function ispeDimensions(bytes: Uint8Array, box: Box): ImageDimensions {
    requireBytes(bytes, box.payload, 12);
    return {
        width: readU32BE(bytes, box.payload + 4),
        height: readU32BE(bytes, box.payload + 8),
    };
}

function associatedPropertyIds(bytes: Uint8Array, box: Box, targetId: number): number[] {
    requireBytes(bytes, box.payload, 8);
    const version = bytes[box.payload]!;
    const flags = (bytes[box.payload + 1]! << 16) | (bytes[box.payload + 2]! << 8) | bytes[box.payload + 3]!;
    let offset = box.payload + 4;
    const entries = readU32BE(bytes, offset);
    offset += 4;
    if (entries > maxBoxes) {
        malformed();
    }
    for (let entry = 0; entry < entries; entry++) {
        const itemId = version < 1 ? readU16BE(bytes, offset) : readU32BE(bytes, offset);
        offset += version < 1 ? 2 : 4;
        requireBytes(bytes, offset, 1);
        const count = bytes[offset++]!;
        const propertyIds: number[] = [];
        for (let association = 0; association < count; association++) {
            const wide = (flags & 1) !== 0;
            const encoded = wide ? readU16BE(bytes, offset) : bytes[offset]!;
            offset += wide ? 2 : 1;
            propertyIds.push(encoded & (wide ? 0x7fff : 0x7f));
        }
        if (itemId === targetId) {
            return propertyIds.filter((id) => id > 0);
        }
    }
    if (offset > box.end) {
        malformed();
    }
    return [];
}

import { HttpError } from "../../core/errors.ts";

export function ascii(bytes: Uint8Array, offset: number, length: number): string {
    if (offset < 0 || length < 0 || offset + length > bytes.length) {
        malformed();
    }
    return String.fromCharCode(...bytes.subarray(offset, offset + length));
}

export function matches(bytes: Uint8Array, offset: number, expected: readonly number[]): boolean {
    return expected.every((byte, index) => bytes[offset + index] === byte);
}

export function readU16BE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 2);
    return (bytes[offset]! << 8) | bytes[offset + 1]!;
}

export function readU16LE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 2);
    return bytes[offset]! | (bytes[offset + 1]! << 8);
}

export function readU24LE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 3);
    return bytes[offset]! | (bytes[offset + 1]! << 8) | (bytes[offset + 2]! << 16);
}

export function readU32BE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 4);
    return new DataView(bytes.buffer, bytes.byteOffset + offset, 4).getUint32(0, false);
}

export function readU32LE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 4);
    return new DataView(bytes.buffer, bytes.byteOffset + offset, 4).getUint32(0, true);
}

export function readU64BE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 8);
    const value = new DataView(bytes.buffer, bytes.byteOffset + offset, 8).getBigUint64(0, false);
    if (value > BigInt(Number.MAX_SAFE_INTEGER)) {
        malformed();
    }
    return Number(value);
}

export function requireBytes(bytes: Uint8Array, offset: number, length: number): void {
    if (offset < 0 || length < 0 || offset + length > bytes.length) {
        malformed();
    }
}

export function malformed(): never {
    throw new HttpError(400, "file is not a valid supported image");
}

export function unsupportedAnimation(): never {
    throw new HttpError(400, "animated images are not supported");
}

export function exifOrientation(bytes: Uint8Array): number | null {
    const tiff = bytes.length >= 6 && ascii(bytes, 0, 6) === "Exif\u0000\u0000" ? bytes.subarray(6) : bytes;
    if (tiff.length < 8) {
        return null;
    }
    const endian = ascii(tiff, 0, 2);
    if (endian !== "II" && endian !== "MM") {
        return null;
    }
    const read16 = endian === "II" ? readU16LE : readU16BE;
    const read32 = endian === "II" ? readU32LE : readU32BE;
    try {
        if (read16(tiff, 2) !== 42) {
            return null;
        }
        const ifdOffset = read32(tiff, 4);
        const count = read16(tiff, ifdOffset);
        if (count > 512) {
            return null;
        }
        for (let index = 0; index < count; index++) {
            const entry = ifdOffset + 2 + index * 12;
            requireBytes(tiff, entry, 12);
            if (read16(tiff, entry) !== 0x0112 || read16(tiff, entry + 2) !== 3 || read32(tiff, entry + 4) !== 1) {
                continue;
            }
            const orientation = read16(tiff, entry + 8);
            return orientation >= 1 && orientation <= 8 ? orientation : null;
        }
    } catch {
        return null;
    }
    return null;
}

import { ascii, malformed, readU16LE, requireBytes, unsupportedAnimation } from "./bytes.ts";
import type { ImageDimensions } from "./types.ts";

export function isGif(bytes: Uint8Array): boolean {
    const header = bytes.length >= 6 ? ascii(bytes, 0, 6) : "";
    return header === "GIF87a" || header === "GIF89a";
}

export function gifDimensions(bytes: Uint8Array): ImageDimensions {
    requireBytes(bytes, 0, 13);
    if (!isGif(bytes)) {
        malformed();
    }
    const dimensions = { width: readU16LE(bytes, 6), height: readU16LE(bytes, 8) };
    let offset = 13 + colorTableLength(bytes[10]!);
    requireBytes(bytes, 0, offset);
    let frames = 0;
    while (offset < bytes.length) {
        const marker = bytes[offset++]!;
        if (marker === 0x3b) {
            if (frames !== 1 || offset !== bytes.length) {
                malformed();
            }
            return dimensions;
        }
        if (marker === 0x21) {
            requireBytes(bytes, offset, 1);
            offset = skipSubBlocks(bytes, offset + 1, false);
            continue;
        }
        if (marker !== 0x2c) {
            malformed();
        }
        frames++;
        if (frames > 1) {
            unsupportedAnimation();
        }
        requireBytes(bytes, offset, 9);
        const left = readU16LE(bytes, offset);
        const top = readU16LE(bytes, offset + 2);
        const width = readU16LE(bytes, offset + 4);
        const height = readU16LE(bytes, offset + 6);
        if (!width || !height || left + width > dimensions.width || top + height > dimensions.height) {
            malformed();
        }
        offset += 9;
        offset += colorTableLength(bytes[offset - 1]!);
        requireBytes(bytes, offset, 1);
        const minimumCodeSize = bytes[offset++]!;
        if (minimumCodeSize < 2 || minimumCodeSize > 8) {
            malformed();
        }
        offset = skipSubBlocks(bytes, offset, true);
    }
    malformed();
}

function colorTableLength(packed: number): number {
    return packed & 0x80 ? 3 * 2 ** ((packed & 0x07) + 1) : 0;
}

function skipSubBlocks(bytes: Uint8Array, start: number, requireData: boolean): number {
    let offset = start;
    let dataBytes = 0;
    while (offset < bytes.length) {
        const length = bytes[offset++]!;
        if (length === 0) {
            if (requireData && dataBytes === 0) {
                malformed();
            }
            return offset;
        }
        requireBytes(bytes, offset, length);
        dataBytes += length;
        offset += length;
    }
    malformed();
}

import { HttpError } from "../../core/errors.ts";
import { maxPhotoPixels } from "../constants.ts";
import { avifDimensions, isAvif } from "./avif.ts";
import { gifDimensions, isGif } from "./gif.ts";
import { isJpeg, jpegDimensions } from "./jpeg.ts";
import { isPng, pngDimensions } from "./png.ts";
import type { ImageDimensions, ProbedImage } from "./types.ts";
import { isWebp, webpDimensions } from "./webp.ts";

export type { ImageDimensions, ProbedImage } from "./types.ts";

export function probePhoto(bytes: Uint8Array): ProbedImage {
    const image = detectedImage(bytes);
    validateDimensions(image);
    return image;
}

function detectedImage(bytes: Uint8Array): ProbedImage {
    if (isJpeg(bytes)) {
        return { ...jpegDimensions(bytes), mimeType: "image/jpeg", extension: ".jpg" };
    }
    if (isPng(bytes)) {
        return { ...pngDimensions(bytes), mimeType: "image/png", extension: ".png" };
    }
    if (isWebp(bytes)) {
        return { ...webpDimensions(bytes), mimeType: "image/webp", extension: ".webp" };
    }
    if (isGif(bytes)) {
        return { ...gifDimensions(bytes), mimeType: "image/gif", extension: ".gif" };
    }
    if (isAvif(bytes)) {
        return { ...avifDimensions(bytes), mimeType: "image/avif", extension: ".avif" };
    }
    throw new HttpError(400, "file must be a JPEG, PNG, WebP, GIF, or AVIF image");
}

function validateDimensions(dimensions: ImageDimensions): void {
    const { width, height } = dimensions;
    if (
        !Number.isSafeInteger(width) ||
        !Number.isSafeInteger(height) ||
        width <= 0 ||
        height <= 0 ||
        width * height > maxPhotoPixels
    ) {
        throw new HttpError(400, "image dimensions are invalid or too large");
    }
}

import { exifOrientation, malformed, matches, readU16BE, requireBytes } from "./bytes.ts";
import type { ImageDimensions } from "./types.ts";

const startOfFrameMarkers = new Set([0xc0, 0xc1, 0xc2, 0xc3, 0xc5, 0xc6, 0xc7, 0xc9, 0xca, 0xcb, 0xcd, 0xce, 0xcf]);

export function isJpeg(bytes: Uint8Array): boolean {
    return matches(bytes, 0, [0xff, 0xd8, 0xff]);
}

export function jpegDimensions(bytes: Uint8Array): ImageDimensions {
    if (!isJpeg(bytes)) {
        malformed();
    }
    let offset = 2;
    let orientation = 1;
    let dimensions: ImageDimensions | null = null;
    let sawQuantization = false;
    let sawCodingTable = false;
    let sawScan = false;
    let sawEnd = false;
    let entropyBytes = 0;
    while (offset < bytes.length) {
        if (bytes[offset] !== 0xff) {
            malformed();
        }
        while (bytes[offset] === 0xff) {
            offset++;
        }
        requireBytes(bytes, offset, 1);
        const marker = bytes[offset++]!;
        if (marker === 0xd9) {
            sawEnd = true;
            break;
        }
        if (marker === 0x00 || marker === 0xd8 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) {
            if (marker === 0x00 || marker === 0xd8) {
                malformed();
            }
            continue;
        }
        const segmentLength = readU16BE(bytes, offset);
        if (segmentLength < 2) {
            malformed();
        }
        const payload = offset + 2;
        const payloadLength = segmentLength - 2;
        requireBytes(bytes, payload, payloadLength);
        if (marker === 0xe1) {
            orientation = exifOrientation(bytes.subarray(payload, payload + payloadLength)) ?? orientation;
        }
        if (marker === 0xdb) {
            sawQuantization = true;
        }
        if (marker === 0xc4 || marker === 0xcc) {
            sawCodingTable = true;
        }
        if (startOfFrameMarkers.has(marker)) {
            requireBytes(bytes, payload, 6);
            const components = bytes[payload + 5]!;
            if (!components || segmentLength !== 8 + components * 3) {
                malformed();
            }
            dimensions = {
                width: readU16BE(bytes, payload + 3),
                height: readU16BE(bytes, payload + 1),
            };
        }
        if (marker === 0xda) {
            if (!dimensions || payloadLength < 6) {
                malformed();
            }
            sawScan = true;
            const scan = scanEntropy(bytes, payload + payloadLength);
            entropyBytes += scan.bytes;
            offset = scan.nextMarker;
            continue;
        }
        offset += segmentLength;
    }
    if (
        !dimensions ||
        !sawQuantization ||
        !sawCodingTable ||
        !sawScan ||
        !sawEnd ||
        entropyBytes === 0 ||
        offset !== bytes.length
    ) {
        malformed();
    }
    return orientation >= 5 && orientation <= 8 ? { width: dimensions.height, height: dimensions.width } : dimensions;
}

function scanEntropy(bytes: Uint8Array, start: number): { bytes: number; nextMarker: number } {
    let offset = start;
    let dataBytes = 0;
    while (offset < bytes.length) {
        if (bytes[offset] !== 0xff) {
            dataBytes++;
            offset++;
            continue;
        }
        const markerStart = offset;
        while (bytes[offset] === 0xff) {
            offset++;
        }
        requireBytes(bytes, offset, 1);
        const marker = bytes[offset]!;
        if (marker === 0x00) {
            dataBytes++;
            offset++;
            continue;
        }
        if (marker >= 0xd0 && marker <= 0xd7) {
            offset++;
            continue;
        }
        return { bytes: dataBytes, nextMarker: markerStart };
    }
    malformed();
}

import { ascii, exifOrientation, malformed, matches, readU32BE, requireBytes, unsupportedAnimation } from "./bytes.ts";
import type { ImageDimensions } from "./types.ts";

const signature = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a] as const;
const crc32Table = buildCrc32Table();

function buildCrc32Table(): Readonly<Uint32Array> {
    const table = new Uint32Array(256);
    for (let value = 0; value < table.length; value++) {
        let crc = value;
        for (let bit = 0; bit < 8; bit++) {
            crc = (crc >>> 1) ^ (crc & 1 ? 0xedb88320 : 0);
        }
        table[value] = crc >>> 0;
    }
    return table;
}

export function isPng(bytes: Uint8Array): boolean {
    return matches(bytes, 0, signature);
}

export function pngDimensions(bytes: Uint8Array): ImageDimensions {
    if (!isPng(bytes)) {
        malformed();
    }
    let offset = signature.length;
    let dimensions: ImageDimensions | null = null;
    let sawImageData = false;
    let imageDataEnded = false;
    let orientation = 1;
    while (offset < bytes.length) {
        requireBytes(bytes, offset, 12);
        const length = readU32BE(bytes, offset);
        const type = ascii(bytes, offset + 4, 4);
        const payload = offset + 8;
        const end = payload + length;
        requireBytes(bytes, payload, length + 4);
        if (crc32(bytes.subarray(offset + 4, end)) !== readU32BE(bytes, end)) {
            malformed();
        }
        if (type === "IHDR") {
            if (dimensions || offset !== signature.length || length !== 13) {
                malformed();
            }
            dimensions = readHeader(bytes, payload);
        } else if (type === "acTL") {
            unsupportedAnimation();
        } else if (type === "eXIf") {
            orientation = exifOrientation(bytes.subarray(payload, end)) ?? orientation;
        } else if (type === "IDAT") {
            if (!dimensions || imageDataEnded || length === 0) {
                malformed();
            }
            sawImageData = true;
        } else if (sawImageData && type !== "IEND") {
            imageDataEnded = true;
        }
        offset = end + 4;
        if (type === "IEND") {
            if (length !== 0 || !dimensions || !sawImageData || offset !== bytes.length) {
                malformed();
            }
            return orientation >= 5 && orientation <= 8
                ? { width: dimensions.height, height: dimensions.width }
                : dimensions;
        }
    }
    malformed();
}

function readHeader(bytes: Uint8Array, offset: number): ImageDimensions {
    const bitDepth = bytes[offset + 8]!;
    const colorType = bytes[offset + 9]!;
    const allowedDepths: Record<number, readonly number[]> = {
        0: [1, 2, 4, 8, 16],
        2: [8, 16],
        3: [1, 2, 4, 8],
        4: [8, 16],
        6: [8, 16],
    };
    if (
        !allowedDepths[colorType]?.includes(bitDepth) ||
        bytes[offset + 10] !== 0 ||
        bytes[offset + 11] !== 0 ||
        (bytes[offset + 12] !== 0 && bytes[offset + 12] !== 1)
    ) {
        malformed();
    }
    return { width: readU32BE(bytes, offset), height: readU32BE(bytes, offset + 4) };
}

function crc32(bytes: Uint8Array): number {
    let crc = 0xffffffff;
    for (let index = 0; index < bytes.length; index++) {
        crc = crc32Table[(crc ^ bytes[index]!) & 0xff]! ^ (crc >>> 8);
    }
    return (crc ^ 0xffffffff) >>> 0;
}

export type ImageDimensions = {
    height: number;
    width: number;
};

export type ProbedImage = ImageDimensions & {
    extension: string;
    mimeType: string;
};

import {
    ascii,
    exifOrientation,
    malformed,
    matches,
    readU16LE,
    readU24LE,
    readU32LE,
    requireBytes,
    unsupportedAnimation,
} from "./bytes.ts";
import type { ImageDimensions } from "./types.ts";

export function isWebp(bytes: Uint8Array): boolean {
    return bytes.length >= 12 && ascii(bytes, 0, 4) === "RIFF" && ascii(bytes, 8, 4) === "WEBP";
}

export function webpDimensions(bytes: Uint8Array): ImageDimensions {
    requireBytes(bytes, 0, 20);
    if (!isWebp(bytes) || readU32LE(bytes, 4) + 8 !== bytes.length) {
        malformed();
    }
    let offset = 12;
    let canvas: ImageDimensions | null = null;
    let frame: ImageDimensions | null = null;
    let orientation = 1;
    while (offset < bytes.length) {
        requireBytes(bytes, offset, 8);
        const kind = ascii(bytes, offset, 4);
        const length = readU32LE(bytes, offset + 4);
        const payload = offset + 8;
        requireBytes(bytes, payload, length);
        if (kind === "ANIM" || kind === "ANMF") {
            unsupportedAnimation();
        }
        if (kind === "EXIF") {
            orientation = exifOrientation(bytes.subarray(payload, payload + length)) ?? orientation;
        }
        if (kind === "VP8X") {
            if (canvas || length !== 10) {
                malformed();
            }
            if (bytes[payload]! & 0x02) {
                unsupportedAnimation();
            }
            canvas = {
                width: readU24LE(bytes, payload + 4) + 1,
                height: readU24LE(bytes, payload + 7) + 1,
            };
        } else if (kind === "VP8L" || kind === "VP8 ") {
            if (frame) {
                malformed();
            }
            frame =
                kind === "VP8L" ? losslessDimensions(bytes, payload, length) : lossyDimensions(bytes, payload, length);
        }
        offset = payload + length + (length % 2);
        requireBytes(bytes, 0, offset);
    }
    if (offset !== bytes.length || !frame) {
        malformed();
    }
    if (canvas && (canvas.width !== frame.width || canvas.height !== frame.height)) {
        malformed();
    }
    const dimensions = canvas ?? frame;
    return orientation >= 5 && orientation <= 8 ? { width: dimensions.height, height: dimensions.width } : dimensions;
}

function losslessDimensions(bytes: Uint8Array, payload: number, length: number): ImageDimensions {
    if (length < 5 || bytes[payload] !== 0x2f) {
        malformed();
    }
    const bits = readU32LE(bytes, payload + 1);
    return {
        width: (bits & 0x3fff) + 1,
        height: ((bits >>> 14) & 0x3fff) + 1,
    };
}

function lossyDimensions(bytes: Uint8Array, payload: number, length: number): ImageDimensions {
    if (length < 10 || !matches(bytes, payload + 3, [0x9d, 0x01, 0x2a])) {
        malformed();
    }
    return {
        width: readU16LE(bytes, payload + 6) & 0x3fff,
        height: readU16LE(bytes, payload + 8) & 0x3fff,
    };
}

import { HttpError } from "../core/errors.ts";
import { optionalText, readJsonObject, requiredId } from "../core/records.ts";
import { maxPhotoBytes } from "./constants.ts";
import { readSingleMultipartFile } from "./multipart.ts";
import { probePhoto } from "./probe/index.ts";

export type UploadedPhoto = {
    extension: string;
    file: File;
    height: number;
    mimeType: string;
    width: number;
};

export async function readPhoto(request: Request): Promise<UploadedPhoto> {
    const multipart = await readSingleMultipartFile(request, maxPhotoBytes);
    const detected = probePhoto(multipart.bytes);
    return {
        ...detected,
        file: new File([multipart.bytes], multipart.filename, { type: detected.mimeType }),
    };
}

export function photoPath(albumId: number, photo: UploadedPhoto): string {
    const date = new Date().toISOString().slice(0, 10);
    return `albums/${albumId}/${date}/${crypto.randomUUID()}${photo.extension}`;
}

export async function readPhotoIds(request: Request): Promise<number[]> {
    const body = await readJsonObject(request);
    if (!Array.isArray(body.photoIds)) {
        throw new HttpError(400, "photoIds must be an array");
    }
    const ids = body.photoIds.map((value, index) => {
        const number = Number(value);
        if (!Number.isSafeInteger(number) || number <= 0) {
            throw new HttpError(400, `photoIds[${index}] must be a positive integer`);
        }
        return number;
    });
    if (new Set(ids).size !== ids.length) {
        throw new HttpError(400, "photoIds must be unique");
    }
    return ids;
}

export function photoUploadIds(request: Request): { albumId: number; replacePhotoId: number | null } {
    return {
        albumId: requiredId(request, "albumId"),
        replacePhotoId: optionalPositiveId(new URL(request.url).searchParams.get("photoId"), "photoId"),
    };
}

function optionalPositiveId(value: string | null, name: string): number | null {
    if (!optionalText(value, name)) {
        return null;
    }
    const number = Number(value);
    if (!Number.isSafeInteger(number) || number <= 0) {
        throw new HttpError(400, `${name} must be a positive integer`);
    }
    return number;
}

import { requiredEnv, serviceRoleKey } from "../core/env.ts";
import { HttpError } from "../core/errors.ts";
import { isRecord } from "../core/records.ts";
import { maxPhotoBytes, photoBucket } from "./constants.ts";

export async function ensurePhotoBucket(): Promise<void> {
    const existing = await storage(`/bucket/${encodeURIComponent(photoBucket)}`, { method: "GET" });
    if (existing.ok) {
        const bucket = await existing.json().catch(() => null);
        if (isRecord(bucket) && bucket.public === false && bucket.file_size_limit === maxPhotoBytes) {
            return;
        }
        const updated = await storage(`/bucket/${encodeURIComponent(photoBucket)}`, {
            method: "PUT",
            headers: { "content-type": "application/json" },
            body: JSON.stringify(bucketConfiguration()),
        });
        if (!updated.ok) {
            throw await storageError(updated);
        }
        return;
    }
    if (!(await isMissingBucket(existing))) {
        throw await storageError(existing);
    }
    const created = await storage("/bucket", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ id: photoBucket, name: photoBucket, ...bucketConfiguration() }),
    });
    if (!created.ok && created.status !== 409) {
        throw await storageError(created);
    }
}

async function isMissingBucket(response: Response): Promise<boolean> {
    if (response.status === 404) {
        return true;
    }
    if (response.status !== 400) {
        return false;
    }
    const body = await response
        .clone()
        .json()
        .catch(() => null);
    return (
        isRecord(body) &&
        (body.error === "Bucket not found" ||
            body.message === "Bucket not found" ||
            body.statusCode === "404" ||
            body.statusCode === 404)
    );
}

function bucketConfiguration(): Record<string, unknown> {
    return {
        public: false,
        file_size_limit: maxPhotoBytes,
        allowed_mime_types: ["image/jpeg", "image/png", "image/webp", "image/gif", "image/avif"],
    };
}

export async function uploadPhoto(path: string, file: File): Promise<void> {
    const response = await storage(objectPath(path), {
        method: "POST",
        headers: {
            "cache-control": "31536000",
            "content-type": file.type,
            "x-upsert": "false",
        },
        body: file,
    });
    if (!response.ok) {
        throw await storageError(response);
    }
}

export async function downloadPhoto(path: string): Promise<Response> {
    const response = await storage(objectPath(path), { method: "GET" });
    if (response.status === 404) {
        throw new HttpError(404, "photo not found");
    }
    if (!response.ok) {
        throw await storageError(response);
    }
    return response;
}

export async function deletePhotoBestEffort(path: string): Promise<void> {
    try {
        const response = await storage(objectPath(path), { method: "DELETE" });
        if (!response.ok && response.status !== 404) {
            console.warn(`Unable to remove unattached photo (${response.status})`);
        }
    } catch (error) {
        console.warn("Unable to remove unattached photo", error);
    }
}

function objectPath(path: string): string {
    const bucket = encodeURIComponent(photoBucket);
    const object = path.split("/").map(encodeURIComponent).join("/");
    return `/object/${bucket}/${object}`;
}

async function storage(path: string, init: RequestInit): Promise<Response> {
    const key = serviceRoleKey();
    const headers = new Headers(init.headers);
    headers.set("apikey", key);
    if (!key.startsWith("sb_")) {
        headers.set("authorization", `Bearer ${key}`);
    }
    const base = requiredEnv("SUPABASE_URL").replace(/\/$/, "");
    return await fetch(`${base}/storage/v1${path}`, { ...init, headers });
}

async function storageError(response: Response): Promise<HttpError> {
    const body = await response.json().catch(() => null);
    const message =
        isRecord(body) && typeof body.message === "string"
            ? body.message
            : `Supabase Storage request failed (${response.status})`;
    return new HttpError(502, message);
}

import { json, methodNotAllowed } from "../core/http.ts";
import { HttpError } from "../core/errors.ts";
import { camelize, optionalInteger, optionalText, readJsonObject, requiredId, requiredText } from "../core/records.ts";
import { rpc } from "../core/rest.ts";

export async function handleAlbumRoute(route: string, request: Request): Promise<Response | null> {
    if (route === "/public/albums") {
        return request.method === "GET" ? await listPublicAlbums(request) : methodNotAllowed("GET");
    }
    if (route === "/public/album") {
        return request.method === "GET" ? await getPublicAlbum(request) : methodNotAllowed("GET");
    }
    if (route === "/albums") {
        return request.method === "GET" ? await listManagedAlbums(request) : methodNotAllowed("GET");
    }
    if (route === "/album") {
        if (request.method === "GET") {
            const id = new URL(request.url).searchParams.get("id");
            const albumId = optionalQueryId(id, "id");
            const album = await rpc("get_managed_album", { p_album_id: albumId });
            if (albumId && album === null) {
                throw new HttpError(404, "album not found");
            }
            return json(camelize(album));
        }
        return request.method === "POST" ? await upsertAlbum(request) : methodNotAllowed("GET", "POST");
    }
    if (route === "/album/archive") {
        return request.method === "POST" ? await archiveAlbum(request) : methodNotAllowed("POST");
    }
    if (route === "/albums/reorder") {
        return request.method === "POST" ? await reorderAlbums(request) : methodNotAllowed("POST");
    }
    return null;
}

async function listPublicAlbums(request: Request): Promise<Response> {
    const params = new URL(request.url).searchParams;
    return rpcResponse("list_public_albums", {
        p_q: optionalText(params.get("q"), "q"),
        p_category_slug: optionalText(params.get("category"), "category"),
        p_limit: nullablePageValue(params.get("limit"), "limit"),
        p_offset: pageValue(params.get("offset"), "offset", 0),
    });
}

async function getPublicAlbum(request: Request): Promise<Response> {
    const slug = optionalText(new URL(request.url).searchParams.get("slug"), "slug");
    if (!slug) {
        throw new HttpError(400, "slug is required");
    }
    const album = await rpc("get_public_album", { p_slug: slug });
    if (album === null) {
        throw new HttpError(404, "album not found");
    }
    return json(camelize(album));
}

async function listManagedAlbums(request: Request): Promise<Response> {
    const params = new URL(request.url).searchParams;
    return rpcResponse("list_managed_albums", {
        p_q: optionalText(params.get("q"), "q"),
        p_status: optionalText(params.get("status"), "status"),
        p_category_id: optionalQueryId(params.get("categoryId"), "categoryId"),
        p_limit: pageValue(params.get("limit"), "limit", 50),
        p_offset: pageValue(params.get("offset"), "offset", 0),
    });
}

async function upsertAlbum(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    return rpcResponse("upsert_album", {
        p_album_id: optionalBodyId(body.id, "id"),
        p_title: requiredText(body.title, "title"),
        p_slug: requiredText(body.slug, "slug"),
        p_description: optionalText(body.description, "description"),
        p_category_id: optionalBodyId(body.categoryId, "categoryId"),
        p_status: optionalText(body.status, "status") ?? "draft",
        p_position: optionalInteger(body.position, "position", 0),
        p_expected_version: optionalVersion(body.version),
    });
}

async function archiveAlbum(request: Request): Promise<Response> {
    const body = await readJsonObject(request).catch(() => ({}));
    return rpcResponse("archive_album", {
        p_album_id: requiredId(request, "id"),
        p_expected_version: optionalVersion(body.version),
    });
}

async function reorderAlbums(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    if (!Array.isArray(body.albumIds)) {
        throw new HttpError(400, "albumIds must be an array");
    }
    return rpcResponse("reorder_albums", {
        p_album_ids: body.albumIds.map((value, index) => {
            const id = optionalBodyId(value, `albumIds[${index}]`);
            if (!id) {
                throw new HttpError(400, `albumIds[${index}] must be a positive integer`);
            }
            return id;
        }),
    });
}

async function rpcResponse(name: string, body: Record<string, unknown>): Promise<Response> {
    return json(camelize(await rpc(name, body)));
}

function pageValue(value: unknown, name: string, fallback: number): number {
    const result = optionalInteger(value, name, fallback);
    if (result < 0) {
        throw new HttpError(400, `${name} must not be negative`);
    }
    return result;
}

function nullablePageValue(value: string | null, name: string): number | null {
    return value === null || value === "" ? null : pageValue(value, name, 0);
}

function optionalQueryId(value: string | null, name: string): number | null {
    return optionalBodyId(value, name);
}

function optionalBodyId(value: unknown, name: string): number | null {
    if (value === undefined || value === null || value === "") {
        return null;
    }
    const id = Number(value);
    if (!Number.isSafeInteger(id) || id <= 0) {
        throw new HttpError(400, `${name} must be a positive integer`);
    }
    return id;
}

function optionalVersion(value: unknown): number | null {
    return value === undefined || value === null ? null : optionalInteger(value, "version", 0);
}

import { json, methodNotAllowed } from "../core/http.ts";
import { HttpError } from "../core/errors.ts";
import { camelize, optionalInteger, optionalText, readJsonObject, requiredId, requiredText } from "../core/records.ts";
import { rpc } from "../core/rest.ts";

export async function handleCategoryRoute(route: string, request: Request): Promise<Response | null> {
    if (route === "/public/categories") {
        return request.method === "GET" ? rpcResponse("list_public_categories") : methodNotAllowed("GET");
    }
    if (route === "/categories") {
        if (request.method !== "GET") {
            return methodNotAllowed("GET");
        }
        const params = new URL(request.url).searchParams;
        return rpcResponse("list_managed_categories", {
            p_q: optionalText(params.get("q"), "q"),
            p_limit: optionalInteger(params.get("limit"), "limit", 100),
            p_offset: optionalInteger(params.get("offset"), "offset", 0),
        });
    }
    if (route === "/category") {
        if (request.method === "GET") {
            const id = new URL(request.url).searchParams.get("id");
            const categoryId = positiveIdOrNull(id, "id");
            const category = await rpc("get_managed_category", { p_category_id: categoryId });
            if (categoryId && category === null) {
                throw new HttpError(404, "category not found");
            }
            return json(camelize(category));
        }
        if (request.method === "POST") {
            return await upsertCategory(request);
        }
        if (request.method === "DELETE") {
            return await deleteCategory(request);
        }
        return methodNotAllowed("GET", "POST", "DELETE");
    }
    if (route === "/categories/reorder") {
        return request.method === "POST" ? await reorderCategories(request) : methodNotAllowed("POST");
    }
    return null;
}

async function upsertCategory(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    return rpcResponse("upsert_category", {
        p_category_id: positiveIdOrNull(body.id, "id"),
        p_name: requiredText(body.name, "name"),
        p_slug: requiredText(body.slug, "slug"),
        p_description: optionalText(body.description, "description"),
        p_position: optionalInteger(body.position, "position", 0),
        p_expected_version: optionalVersion(body.version),
    });
}

async function deleteCategory(request: Request): Promise<Response> {
    const body = await readJsonObject(request).catch(() => ({}));
    return rpcResponse("delete_category", {
        p_category_id: requiredId(request, "id"),
        p_expected_version: optionalVersion(body.version),
    });
}

async function reorderCategories(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    return rpcResponse("reorder_categories", {
        p_category_ids: positiveIds(body.categoryIds, "categoryIds"),
    });
}

async function rpcResponse(name: string, body: Record<string, unknown> = {}): Promise<Response> {
    return json(camelize(await rpc(name, body)));
}

function positiveIds(value: unknown, name: string): number[] {
    if (!Array.isArray(value)) {
        throw new HttpError(400, `${name} must be an array`);
    }
    return value.map((item, index) => {
        const id = positiveIdOrNull(item, `${name}[${index}]`);
        if (!id) {
            throw new HttpError(400, `${name}[${index}] must be a positive integer`);
        }
        return id;
    });
}

function positiveIdOrNull(value: unknown, name: string): number | null {
    if (value === undefined || value === null || value === "") {
        return null;
    }
    const id = Number(value);
    if (!Number.isSafeInteger(id) || id <= 0) {
        throw new HttpError(400, `${name} must be a positive integer`);
    }
    return id;
}

function optionalVersion(value: unknown): number | null {
    return value === undefined || value === null ? null : optionalInteger(value, "version", 0);
}

import { HttpError } from "../core/errors.ts";
import { corsHeaders, json, methodNotAllowed } from "../core/http.ts";
import { camelize, isRecord, optionalText, readJsonObject, requiredId, requiredInteger } from "../core/records.ts";
import { rpc, rpcRecord } from "../core/rest.ts";
import { photoBucket } from "../media/constants.ts";
import { photoPath, photoUploadIds, readPhoto, readPhotoIds } from "../media/request.ts";
import { deletePhotoBestEffort, downloadPhoto, ensurePhotoBucket, uploadPhoto } from "../media/storage.ts";

export async function handlePhotoRoute(route: string, request: Request): Promise<Response | null> {
    if (route === "/public/photo" || route === "/photo") {
        if (request.method !== "GET") {
            return methodNotAllowed("GET");
        }
        return await getPhoto(request, route === "/public/photo");
    }
    if (route === "/photos/upload" || route === "/photos/replace") {
        if (request.method !== "POST") {
            return methodNotAllowed("POST");
        }
        return await attachPhoto(request, route === "/photos/replace");
    }
    if (route === "/photos/remove") {
        return request.method === "POST" ? await removePhoto(request) : methodNotAllowed("POST");
    }
    if (route === "/photos/reorder") {
        return request.method === "POST" ? await reorderPhotos(request) : methodNotAllowed("POST");
    }
    if (route === "/photo/metadata") {
        if (request.method === "GET") {
            const photo = await rpc("get_managed_photo", { p_photo_id: requiredId(request, "id") });
            if (photo === null) {
                throw new HttpError(404, "photo not found");
            }
            return json(camelize(photo));
        }
        return request.method === "POST" ? await updateMetadata(request) : methodNotAllowed("GET", "POST");
    }
    return null;
}

async function attachPhoto(request: Request, replacing: boolean): Promise<Response> {
    const ids = photoUploadIds(request);
    if (replacing && !ids.replacePhotoId) {
        throw new HttpError(400, "photoId is required");
    }
    if (!replacing && ids.replacePhotoId) {
        throw new HttpError(400, "photoId is not allowed for upload");
    }
    const authorized = await rpcRecord("authorize_photo_upload", {
        p_album_id: ids.albumId,
        p_replace_photo_id: ids.replacePhotoId,
    });
    if (authorized.state === "not_found") {
        throw new HttpError(404, "album or replacement photo not found");
    }
    if (authorized.state === "limit_reached") {
        throw new HttpError(409, "album photo limit reached");
    }
    if (
        authorized.state !== "authorized" ||
        authorized.album_id !== ids.albumId ||
        authorized.replace_photo_id !== ids.replacePhotoId
    ) {
        throw new HttpError(502, "authorize_photo_upload returned an invalid response");
    }

    const image = await readPhoto(request);
    const path = photoPath(ids.albumId, image);
    await ensurePhotoBucket();
    try {
        await uploadPhoto(path, image.file);
    } catch (error) {
        await deletePhotoBestEffort(path);
        throw error;
    }

    let result: unknown;
    try {
        const params = new URL(request.url).searchParams;
        result = await rpc("attach_album_photo", {
            p_album_id: ids.albumId,
            p_storage_bucket: photoBucket,
            p_storage_path: path,
            p_mime_type: image.mimeType,
            p_file_size: image.file.size,
            p_width: image.width,
            p_height: image.height,
            p_original_filename: image.file.name || null,
            p_alt: optionalText(params.get("alt"), "alt"),
            p_caption: optionalText(params.get("caption"), "caption"),
            p_taken_at: optionalText(params.get("takenAt"), "takenAt"),
            p_replace_photo_id: ids.replacePhotoId,
        });
    } catch (error) {
        if (error instanceof HttpError && error.status >= 400 && error.status < 500) {
            await deletePhotoBestEffort(path);
        }
        throw error;
    }
    return json(camelize(result));
}

async function getPhoto(request: Request, publiclyVisible: boolean): Promise<Response> {
    const photoId = requiredId(request, "id");
    const functionName = publiclyVisible ? "get_public_photo_context" : "get_managed_photo_context";
    const context = await rpcRecord(functionName, { p_photo_id: photoId });
    const photo = context.state === "ok" && isRecord(context.photo) ? context.photo : null;
    if (!photo || photo.storage_bucket !== photoBucket || typeof photo.storage_path !== "string") {
        throw new HttpError(404, "photo not found");
    }
    const stored = await downloadPhoto(photo.storage_path);
    const headers = new Headers(corsHeaders);
    copyHeader(stored, headers, "content-type", stringOrNull(photo.mime_type) ?? "application/octet-stream");
    copyHeader(stored, headers, "etag");
    copyHeader(stored, headers, "last-modified");
    headers.set("cache-control", publiclyVisible ? "public, max-age=31536000, immutable" : "private, no-store");
    return new Response(stored.body, { status: 200, headers });
}

async function removePhoto(request: Request): Promise<Response> {
    return json(
        camelize(
            await rpc("detach_album_photo", {
                p_album_id: requiredId(request, "albumId"),
                p_photo_id: requiredId(request, "photoId"),
            }),
        ),
    );
}

async function reorderPhotos(request: Request): Promise<Response> {
    return json(
        camelize(
            await rpc("reorder_album_photos", {
                p_album_id: requiredId(request, "albumId"),
                p_photo_ids: await readPhotoIds(request),
            }),
        ),
    );
}

async function updateMetadata(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    return json(
        camelize(
            await rpc("update_album_photo", {
                p_album_id: requiredId(request, "albumId"),
                p_photo_id: requiredId(request, "id"),
                p_alt: optionalText(body.alt, "alt"),
                p_caption: optionalText(body.caption, "caption"),
                p_taken_at: optionalText(body.takenAt, "takenAt"),
                p_expected_version: requiredInteger(body.version, "version"),
            }),
        ),
    );
}

function copyHeader(source: Response, target: Headers, name: string, fallback?: string): void {
    const value = source.headers.get(name) ?? fallback;
    if (value) {
        target.set(name, value);
    }
}

function stringOrNull(value: unknown): string | null {
    return typeof value === "string" ? value : null;
}

import { json, methodNotAllowed } from "../core/http.ts";
import { camelize, readJsonObject, requiredBoolean, requiredInteger, requiredText } from "../core/records.ts";
import { rpc } from "../core/rest.ts";

export async function handleSettingsRoute(route: string, request: Request): Promise<Response | null> {
    if (route !== "/settings") {
        return null;
    }
    if (request.method === "GET") {
        return json(camelize(await rpc("get_settings")));
    }
    if (request.method === "POST") {
        const body = await readJsonObject(request);
        const result = await rpc("update_settings", {
            p_gallery_title: requiredText(body.galleryTitle, "galleryTitle"),
            p_default_page_size: requiredInteger(body.defaultPageSize, "defaultPageSize"),
            p_max_photos_per_album: requiredInteger(body.maxPhotosPerAlbum, "maxPhotosPerAlbum"),
            p_allow_downloads: requiredBoolean(body.allowDownloads, "allowDownloads"),
            p_show_captions: requiredBoolean(body.showCaptions, "showCaptions"),
            p_show_taken_at: requiredBoolean(body.showTakenAt, "showTakenAt"),
            p_expected_version: requiredInteger(body.version, "version"),
        });
        return json(camelize(result));
    }
    return methodNotAllowed("GET", "POST");
}

import { json, methodNotAllowed } from "../core/http.ts";
import { ensurePhotoBucket } from "../media/storage.ts";

export async function handleSetupRoute(route: string, request: Request): Promise<Response | null> {
    if (route === "/health") {
        return request.method === "GET" ? json({ ok: true }) : methodNotAllowed("GET");
    }
    if (route === "/setup") {
        if (request.method !== "POST") {
            return methodNotAllowed("POST");
        }
        await ensurePhotoBucket();
        return json({ ok: true });
    }
    return null;
}

