create or replace function photo_albums.upsert_album(
    p_slug text,
    p_title text,
    p_album_id bigint default null,
    p_expected_version integer default null,
    p_description text default null,
    p_category_id bigint default null,
    p_status text default 'draft',
    p_position integer default 0,
    p_actor text default null
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_id bigint;
    v_actor text := nullif(btrim(p_actor), '');
begin
    if p_album_id is null then
        if coalesce(p_status, 'draft') <> 'draft' then
            raise exception 'validation: new albums must start as drafts';
        end if;

        insert into photo_albums.albums (
            slug, title, description, category_id, status, position,
            created_by, updated_by
        )
        values (
            lower(btrim(p_slug)),
            btrim(p_title),
            nullif(btrim(p_description), ''),
            p_category_id,
            'draft',
            coalesce(p_position, 0),
            v_actor,
            v_actor
        )
        returning id into v_id;
    else
        if p_expected_version is null then
            raise exception 'validation: expected album version is required';
        end if;
        perform 1
        from photo_albums.albums
        where id = p_album_id
          and version = p_expected_version
        for update;
        if not found then
            raise exception 'conflict: album version changed or album was not found';
        end if;
        if p_status = 'published' and not exists (
            select 1
            from photo_albums.photos
            where album_id = p_album_id and detached_at is null
        ) then
            raise exception 'validation: a published album requires at least one photo';
        end if;

        update photo_albums.albums
        set
            slug = lower(btrim(p_slug)),
            title = btrim(p_title),
            description = nullif(btrim(p_description), ''),
            category_id = p_category_id,
            status = coalesce(p_status, 'draft'),
            published_at = case
                when p_status = 'published' then coalesce(published_at, now())
                when p_status = 'draft' then null
                else published_at
            end,
            position = coalesce(p_position, 0),
            version = version + 1,
            updated_by = v_actor
        where id = p_album_id
          and version = p_expected_version
        returning id into v_id;

        if v_id is null then
            raise exception 'conflict: album version changed or album was not found';
        end if;
    end if;

    return photo_albums.get_managed_album(v_id);
end;
$$;

create or replace function photo_albums.archive_album(
    p_album_id bigint,
    p_expected_version integer,
    p_actor text default null
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_id bigint;
begin
    update photo_albums.albums
    set
        status = 'archived',
        version = version + 1,
        updated_by = nullif(btrim(p_actor), '')
    where id = p_album_id
      and version = p_expected_version
      and status <> 'archived'
    returning id into v_id;

    if v_id is null then
        raise exception 'conflict: album version changed, is archived, or was not found';
    end if;

    return photo_albums.get_managed_album(v_id);
end;
$$;

create or replace function photo_albums.reorder_albums(
    p_album_ids bigint[],
    p_actor text default null
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_count integer;
    v_unique_count integer;
    v_actor text := nullif(btrim(p_actor), '');
begin
    if p_album_ids is null or cardinality(p_album_ids) = 0 then
        raise exception 'validation: album_ids must not be empty';
    end if;

    select count(*) into v_count
    from photo_albums.albums
    where status <> 'archived';
    select count(distinct id) into v_unique_count
    from unnest(p_album_ids) as requested(id);

    if cardinality(p_album_ids) <> v_unique_count
       or cardinality(p_album_ids) <> v_count
       or exists (
           select 1
           from photo_albums.albums a
           where a.status <> 'archived'
             and not a.id = any(p_album_ids)
       )
    then
        raise exception 'validation: album_ids must contain every active album exactly once';
    end if;

    update photo_albums.albums a
    set
        position = requested.ordinality::integer - 1,
        version = a.version + 1,
        updated_by = v_actor
    from unnest(p_album_ids) with ordinality as requested(id, ordinality)
    where a.id = requested.id and a.status <> 'archived';

    return jsonb_build_object('album_ids', to_jsonb(p_album_ids));
end;
$$;

create or replace function photo_albums.upsert_category(
    p_slug text,
    p_name text,
    p_category_id bigint default null,
    p_expected_version integer default null,
    p_description text default null,
    p_position integer default 0,
    p_actor text default null
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_id bigint;
    v_actor text := nullif(btrim(p_actor), '');
begin
    if p_category_id is null then
        insert into photo_albums.categories (
            slug, name, description, position, created_by, updated_by
        )
        values (
            lower(btrim(p_slug)),
            btrim(p_name),
            nullif(btrim(p_description), ''),
            coalesce(p_position, 0),
            v_actor,
            v_actor
        )
        returning id into v_id;
    else
        if p_expected_version is null then
            raise exception 'validation: expected category version is required';
        end if;

        update photo_albums.categories
        set
            slug = lower(btrim(p_slug)),
            name = btrim(p_name),
            description = nullif(btrim(p_description), ''),
            position = coalesce(p_position, 0),
            version = version + 1,
            updated_by = v_actor
        where id = p_category_id
          and version = p_expected_version
        returning id into v_id;

        if v_id is null then
            raise exception 'conflict: category version changed or category was not found';
        end if;
    end if;

    return photo_albums.get_managed_category(v_id);
end;
$$;

create or replace function photo_albums.delete_category(
    p_category_id bigint,
    p_expected_version integer
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_id bigint;
begin
    if exists (
        select 1
        from photo_albums.albums
        where category_id = p_category_id
    ) then
        raise exception 'conflict: category is used by an album';
    end if;

    delete from photo_albums.categories
    where id = p_category_id
      and version = p_expected_version
    returning id into v_id;

    if v_id is null then
        raise exception 'conflict: category version changed or category was not found';
    end if;

    return jsonb_build_object('deleted', true, 'id', v_id);
end;
$$;

create or replace function photo_albums.reorder_categories(
    p_category_ids bigint[],
    p_actor text default null
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_count integer;
    v_unique_count integer;
    v_actor text := nullif(btrim(p_actor), '');
begin
    if p_category_ids is null or cardinality(p_category_ids) = 0 then
        raise exception 'validation: category_ids must not be empty';
    end if;

    select count(*) into v_count from photo_albums.categories;
    select count(distinct id) into v_unique_count
    from unnest(p_category_ids) as requested(id);

    if cardinality(p_category_ids) <> v_unique_count
       or cardinality(p_category_ids) <> v_count
       or exists (
           select 1
           from photo_albums.categories c
           where not c.id = any(p_category_ids)
       )
    then
        raise exception 'validation: category_ids must contain every category exactly once';
    end if;

    update photo_albums.categories c
    set
        position = requested.ordinality::integer - 1,
        version = c.version + 1,
        updated_by = v_actor
    from unnest(p_category_ids) with ordinality as requested(id, ordinality)
    where c.id = requested.id;

    return jsonb_build_object('category_ids', to_jsonb(p_category_ids));
end;
$$;

create or replace function photo_albums.authorize_photo_upload(
    p_album_id bigint,
    p_replace_photo_id bigint default null
)
returns jsonb
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
    v_status text;
    v_position integer;
    v_count integer;
    v_limit integer;
begin
    select status into v_status
    from photo_albums.albums
    where id = p_album_id;

    if v_status is null or v_status = 'archived' then
        return jsonb_build_object('state', 'not_found');
    end if;

    if p_replace_photo_id is not null then
        select position into v_position
        from photo_albums.photos
        where id = p_replace_photo_id
          and album_id = p_album_id
          and detached_at is null;
        if v_position is null then
            return jsonb_build_object('state', 'not_found');
        end if;
    else
        select count(*)::integer, coalesce(max(position), -1) + 1
        into v_count, v_position
        from photo_albums.photos
        where album_id = p_album_id and detached_at is null;
        select max_photos_per_album into v_limit
        from photo_albums.settings
        where id;
        if v_count >= coalesce(v_limit, 200) then
            return jsonb_build_object('state', 'limit_reached');
        end if;
    end if;

    return jsonb_build_object(
        'state', 'authorized',
        'album_id', p_album_id,
        'replace_photo_id', p_replace_photo_id,
        'position', v_position
    );
end;
$$;

create or replace function photo_albums.attach_album_photo(
    p_album_id bigint,
    p_storage_bucket text,
    p_storage_path text,
    p_mime_type text,
    p_file_size bigint,
    p_width integer,
    p_height integer,
    p_original_filename text,
    p_replace_photo_id bigint default null,
    p_alt text default null,
    p_caption text default null,
    p_taken_at timestamptz default null,
    p_actor text default null
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_status text;
    v_position integer;
    v_count integer;
    v_limit integer;
    v_photo_id bigint;
    v_actor text := nullif(btrim(p_actor), '');
begin
    select status into v_status
    from photo_albums.albums
    where id = p_album_id
    for update;

    if v_status is null or v_status = 'archived' then
        raise exception 'not_found: album';
    end if;

    select count(*)::integer, coalesce(max(position), -1) + 1
    into v_count, v_position
    from photo_albums.photos
    where album_id = p_album_id and detached_at is null;
    select max_photos_per_album into v_limit
    from photo_albums.settings
    where id;

    if p_replace_photo_id is null then
        if v_count >= coalesce(v_limit, 200) then
            raise exception 'conflict: album photo limit reached';
        end if;
    else
        select position into v_position
        from photo_albums.photos
        where id = p_replace_photo_id
          and album_id = p_album_id
          and detached_at is null
        for update;
        if v_position is null then
            raise exception 'not_found: replacement photo';
        end if;
        update photo_albums.photos
        set detached_at = now(), updated_by = v_actor
        where id = p_replace_photo_id;
    end if;

    insert into photo_albums.photos (
        album_id, storage_bucket, storage_path, mime_type, file_size,
        width, height, original_filename, alt, caption, taken_at,
        position, created_by, updated_by
    )
    values (
        p_album_id, p_storage_bucket, btrim(p_storage_path), lower(btrim(p_mime_type)),
        p_file_size, p_width, p_height,
        coalesce(nullif(btrim(p_original_filename), ''), 'upload'),
        nullif(btrim(p_alt), ''), nullif(btrim(p_caption), ''), p_taken_at,
        v_position, v_actor, v_actor
    )
    returning id into v_photo_id;

    return photo_albums.get_managed_photo(v_photo_id);
end;
$$;

create or replace function photo_albums.update_album_photo(
    p_album_id bigint,
    p_photo_id bigint,
    p_expected_version integer,
    p_alt text default null,
    p_caption text default null,
    p_taken_at timestamptz default null,
    p_actor text default null
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_id bigint;
begin
    update photo_albums.photos
    set
        alt = nullif(btrim(p_alt), ''),
        caption = nullif(btrim(p_caption), ''),
        taken_at = p_taken_at,
        version = version + 1,
        updated_by = nullif(btrim(p_actor), '')
    where id = p_photo_id
      and album_id = p_album_id
      and detached_at is null
      and version = p_expected_version
    returning id into v_id;

    if v_id is null then
        raise exception 'conflict: photo version changed or photo was not found';
    end if;
    return photo_albums.get_managed_photo(v_id);
end;
$$;

create or replace function photo_albums.detach_album_photo(
    p_album_id bigint,
    p_photo_id bigint,
    p_actor text default null
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_status text;
    v_count integer;
    v_detached_at timestamptz;
begin
    select status into v_status
    from photo_albums.albums
    where id = p_album_id
    for update;
    if v_status is null or v_status = 'archived' then
        raise exception 'not_found: album';
    end if;

    select count(*)::integer into v_count
    from photo_albums.photos
    where album_id = p_album_id and detached_at is null;
    if v_status = 'published' and v_count <= 1 then
        raise exception 'conflict: a published album requires at least one photo';
    end if;

    update photo_albums.photos
    set
        detached_at = now(),
        updated_by = nullif(btrim(p_actor), '')
    where id = p_photo_id
      and album_id = p_album_id
      and detached_at is null
    returning detached_at into v_detached_at;
    if v_detached_at is null then
        raise exception 'not_found: photo';
    end if;

    return jsonb_build_object(
        'removed', true,
        'photo_id', p_photo_id,
        'detached_at', v_detached_at
    );
end;
$$;

create or replace function photo_albums.reorder_album_photos(
    p_album_id bigint,
    p_photo_ids bigint[],
    p_actor text default null
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_count integer;
    v_unique_count integer;
    v_shift integer;
    v_actor text := nullif(btrim(p_actor), '');
begin
    perform 1
    from photo_albums.albums
    where id = p_album_id and status <> 'archived'
    for update;
    if not found then
        raise exception 'not_found: album';
    end if;
    if p_photo_ids is null or cardinality(p_photo_ids) = 0 then
        raise exception 'validation: photo_ids must not be empty';
    end if;

    select count(*)::integer, coalesce(max(position), -1) + cardinality(p_photo_ids) + 1
    into v_count, v_shift
    from photo_albums.photos
    where album_id = p_album_id and detached_at is null;
    select count(distinct id) into v_unique_count
    from unnest(p_photo_ids) as requested(id);

    if cardinality(p_photo_ids) <> v_count
       or cardinality(p_photo_ids) <> v_unique_count
       or exists (
           select 1
           from photo_albums.photos p
           where p.album_id = p_album_id
             and p.detached_at is null
             and not p.id = any(p_photo_ids)
       )
    then
        raise exception 'validation: photo_ids must contain every attached photo exactly once';
    end if;

    update photo_albums.photos
    set position = position + v_shift, updated_by = v_actor
    where album_id = p_album_id and detached_at is null;

    update photo_albums.photos p
    set
        position = requested.ordinality::integer - 1,
        version = p.version + 1,
        updated_by = v_actor
    from unnest(p_photo_ids) with ordinality as requested(id, ordinality)
    where p.id = requested.id and p.album_id = p_album_id;

    return jsonb_build_object('photo_ids', to_jsonb(p_photo_ids));
end;
$$;

